insert into public.prayers (id, slug, category, country_code, language_code, title, body, editorial_source, sort_order, is_published, audio_path)
values
  ('3a3ea66d-2dea-4264-859d-17f0298f7bdf', 'cuvine-se-cu-adevarat', 'Maica Domnului', null, 'ro', 'Cuvine-se cu adevărat', 'Cuvine-se cu adevărat să te fericim, Născătoare de Dumnezeu, cea pururea fericită și prea nevinovată și Maica Dumnezeului nostru. Ceea ce ești mai cinstită decât heruvimii și mai mărită fără de asemănare decât serafimii, care fără stricăciune pe Dumnezeu-Cuvântul ai născut, pe tine, cea cu adevărat Născătoare de Dumnezeu, te mărim.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 40, true, 'ro/cuvine-se-cu-adevarat.mp3'),
  ('7287ebde-ab7c-40f2-b10e-6db780a91a47', 'imparate-ceresc', 'Începutul rugăciunilor', null, 'ro', 'Împărate ceresc', 'Împărate ceresc, Mângâietorule, Duhul adevărului, Care pretutindenea ești și toate le împlinești, Vistierul bunătăților și Dătătorule de viață, vino și Te sălășluiește întru noi și ne curățește pe noi de toată întinăciunea și mântuiește, Bunule, sufletele noastre.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 30, true, 'ro/imparate-ceresc.mp3'),
  ('5348f7d1-05f9-419b-9d41-2587a432849b', 'nascatoare-de-dumnezeu-fecioara', 'Maica Domnului', null, 'ro', 'Născătoare de Dumnezeu Fecioară', 'Născătoare de Dumnezeu Fecioară, bucură-te, ceea ce ești plină de har, Marie, Domnul este cu tine. Binecuvântată ești tu între femei și binecuvântat este rodul pântecelui tău, că ai născut pe Mântuitorul sufletelor noastre.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 80, true, 'ro/nascatoare-de-dumnezeu-fecioara.mp3'),
  ('dc3c47b6-6aec-492e-897e-a79c0c108baa', 'preasfanta-treime', 'Începutul rugăciunilor', null, 'ro', 'Preasfântă Treime', 'Preasfântă Treime, miluiește-ne pe noi. Doamne, curățește păcatele noastre. Stăpâne, iartă fărădelegile noastre. Sfinte, cercetează și vindecă neputințele noastre, pentru numele Tău.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 60, true, 'ro/preasfanta-treime.mp3'),
  ('59c906f4-8843-4e2a-af0c-a36d36fa6091', 'rugaciunea-lui-iisus', 'Rugăciuni de bază', null, 'ro', 'Rugăciunea lui Iisus', 'Doamne Iisuse Hristoase, Fiul lui Dumnezeu, miluiește-mă pe mine, păcătosul.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 20, true, 'ro/rugaciunea-lui-iisus.mp3'),
  ('3340db45-4880-4c63-a0da-3d1a46f8bcc4', 'rugaciunea-vamesului', 'Rugăciuni scurte', null, 'ro', 'Rugăciunea vameșului', 'Dumnezeule, milostiv fii mie, păcătosului.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 100, true, 'ro/rugaciunea-vamesului.mp3'),
  ('727d2739-d2d7-460a-a2af-8544e31a326f', 'sfinte-dumnezeule', 'Rugăciuni de bază', null, 'ro', 'Sfinte Dumnezeule', 'Sfinte Dumnezeule, Sfinte tare, Sfinte fără de moarte, miluiește-ne pe noi.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 50, true, 'ro/sfinte-dumnezeule.mp3'),
  ('27814d0e-9f8f-4641-8b9c-ae1063abb4b0', 'slava-tatalui', 'Rugăciuni de bază', null, 'ro', 'Slavă Tatălui', 'Slavă Tatălui și Fiului și Sfântului Duh, și acum și pururea și în vecii vecilor. Amin.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 70, true, 'ro/slava-tatalui.mp3'),
  ('abff4081-627e-40b5-8251-0ef15ec688f3', 'sub-milostivirea-ta', 'Maica Domnului', null, 'ro', 'Sub milostivirea ta', 'Sub milostivirea ta scăpăm, Născătoare de Dumnezeu; rugăciunile noastre nu le trece cu vederea întru nevoi, ci din primejdii ne izbăvește pe noi, una curată, una binecuvântată.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 90, true, 'ro/sub-milostivirea-ta.mp3'),
  ('0193b115-155d-4146-b142-105e1a13f2bd', 'tatal-nostru', 'Rugăciuni de bază', null, 'ro', 'Tatăl nostru', 'Tatăl nostru, Care ești în ceruri, sfințească-se numele Tău, vie împărăția Ta, facă-se voia Ta, precum în cer, așa și pe pământ. Pâinea noastră cea spre ființă dă-ne-o nouă astăzi și ne iartă nouă greșelile noastre, precum și noi iertăm greșiților noștri. Și nu ne duce pe noi în ispită, ci ne izbăvește de cel rău. Amin.', 'Text tradițional ortodox. Validarea editorială finală este necesară înainte de lansare.', 10, true, 'ro/tatal-nostru.mp3')
